TOOLS=r'المنهاج ، الكتاب المدرسي ، الآلة الحاسبة العلمية ، برمجية Geogebra.'
S=[]
# ---------------------------------------------------------------- 10
S.append(sess('10',r'الدالة الأسية النيبيرية: تعريف وخواص جبرية',
[r'المشتقة ، مشتقة جداء وحاصل قسمة ، الدالة الثابتة (مشتقتها معدومة).'],
[r'معرفة الدالة الأسية كحل وحيد للمسألة $f^{\prime}=f$ و $f(0)=1$.',r'توظيف الخواص الجبرية للدالة الأسية والترميز $e^x$.'],TOOLS,
r'هل توجد دالة مشتقتها تساويها؟',
ACT('01')+r'\ (نشاط 01 صفحة 76) نقبل وجود دالة $f$ قابلة للاشتقاق على $\mathbb R$ تحقق: $f^{\prime}=f$ و $f(0)=1$.'
+Q(r'نعتبر الدالة $h$ المعرفة على $\mathbb R$ بـ: $h(x)=f(x)\times f(-x)$. بيّن أن $h$ ثابتة ، واستنتج أن $h(x)=1$.',
   r'بيّن أن $f(x)\neq0$ من أجل كل $x$ من $\mathbb R$.',
   r'نفرض أنه توجد دالة ثانية $g$ تحقق $g^{\prime}=g$ و $g(0)=1$. باستعمال $k(x)=\dfrac{g(x)}{f(x)}$ بيّن أن $g=f$.',
   r'ليكن $y$ عددًا حقيقيًا ثابتًا و $i(x)=\dfrac{f(x+y)}{f(x)}$. بيّن أن $f(x+y)=f(x)\times f(y)$.')
+DIS()+QN(1,T('إثبات أن $h$ ثابتة:')+r' $h$ قابلة للاشتقاق على $\mathbb R$ و:\par $h^{\prime}(x)=f^{\prime}(x)f(-x)+f(x)\times\big[-f^{\prime}(-x)\big]=f(x)f(-x)-f(x)f(-x)=\RR{0}$ (لأن $f^{\prime}=f$).\par إذن $h$ ثابتة على $\mathbb R$ ، و $h(x)=h(0)=f(0)\times f(0)=\RR{1}$.')
+QN(2,T(r'إثبات أن $f(x)\neq0$:')+r' نفرض بالخلف أنه يوجد $x_0$ حيث $f(x_0)=0$: عندئذ $h(x_0)=f(x_0)f(-x_0)=0$ ، وهذا يناقض $h(x_0)=1$. إذن \RR{$f(x)\neq0$ من أجل كل $x$}.')
+QN(3,T('الوحدانية:')+r' $k$ معرفة لأن $f$ لا تنعدم ، و:\par $k^{\prime}(x)=\dfrac{g^{\prime}(x)f(x)-g(x)f^{\prime}(x)}{\big(f(x)\big)^2}=\dfrac{g(x)f(x)-g(x)f(x)}{\big(f(x)\big)^2}=0$.\par إذن $k$ ثابتة و $k(x)=k(0)=\dfrac{g(0)}{f(0)}=1$ ، أي \RR{$g(x)=f(x)$}: الدالة $f$ \RR{وحيدة}.')
+QN(4,T('الخاصية الأساسية:')+r' $i^{\prime}(x)=\dfrac{f(x+y)f(x)-f(x+y)f(x)}{\big(f(x)\big)^2}=0$ ، إذن $i$ ثابتة:\par $i(x)=i(0)=\dfrac{f(y)}{f(0)}=f(y)$ ، ومنه \RR{$f(x+y)=f(x)\times f(y)$}.'),
THM('مبرهنة وتعريف')+r'\ توجد دالة \textbf{وحيدة} $f$ قابلة للاشتقاق على $\mathbb R$ حيث $f^{\prime}=f$ و $f(0)=1$. تسمى \textbf{الدالة الأسية النيبيرية} ونرمز لها بالرمز $\exp$.'
+L('cRem','نتائج')+Q(r'$\RR{\exp(0)=1}$.',r'$\RR{\exp^{\prime}(x)=\exp(x)}$ من أجل كل $x$ من $\mathbb R$.')
+PRO('خواص جبرية')+r'\ من أجل كل عددين حقيقيين $x$ و $y$ ومن أجل كل عدد صحيح $n$:'
+Q(r'$\exp(x)\neq0$.',r'$\exp(x)\times\exp(-x)=1$ ، أي $\RR{\exp(-x)=\dfrac1{\exp(x)}}$.',r'$\RR{\exp(x+y)=\exp(x)\times\exp(y)}$.',r'$\RR{\exp(x-y)=\dfrac{\exp(x)}{\exp(y)}}$.',r'$\RR{\exp(nx)=\big[\exp(x)\big]^n}$.')
+PRF()+QN(4,r'$\exp(x-y)=\exp\big(x+(-y)\big)=\exp(x)\times\exp(-y)$')+r'\par $\exp(x-y)=\exp(x)\times\dfrac1{\exp(y)}=\dfrac{\exp(x)}{\exp(y)}$.'+QN(5,r'الدالة $j(x)=\dfrac{\exp(nx)}{\big[\exp(x)\big]^n}$ مشتقتها معدومة ، إذن $j(x)=j(0)=1$.')
+DEF('العدد $e$ والترميز $e^x$')+Q(r'العدد $e$ هو صورة العدد $1$ بالدالة الأسية: $\RR{e=\exp(1)\approx2{,}718281}$.',r'من أجل كل عدد صحيح $n$: $\exp(n)=\exp(n\times1)=\big[\exp(1)\big]^n=e^n$.',r'نصطلح: من أجل كل عدد حقيقي $x$ نكتب $\RR{\exp(x)=e^x}$.')
+PRO('قواعد الحساب')+r'\ من أجل كل عددين حقيقيين $x$ و $y$ ومن أجل كل عدد صحيح $n$:'
+Q(r'$(e^x)^{\prime}=e^x$ ؛ $e^0=1$ ؛ $e^1=e$.',r'$e^x\times e^{-x}=1$ ، أي $e^{-x}=\dfrac1{e^x}$.',r'$e^{x+y}=e^x\times e^y$ ؛ $e^{x-y}=\dfrac{e^x}{e^y}$ ؛ $e^{nx}=\big(e^x\big)^n$.')
+EX('أمثلة')+Q(r'$A=e^{2x}\times e^{-x+1}=e^{2x-x+1}=\RR{e^{x+1}}$.',
   r'$B=\dfrac{\big(e^x\big)^3}{e^{2x-1}}=\dfrac{e^{3x}}{e^{2x-1}}=e^{3x-(2x-1)}=\RR{e^{x+1}}$.',
   r'$C=\big(e^x+e^{-x}\big)^2=e^{2x}+2e^x e^{-x}+e^{-2x}=\RR{e^{2x}+2+e^{-2x}}$.',
   r'من أجل كل $x$: $\dfrac{e^x-1}{e^x+1}=\dfrac{e^{-x}\big(e^x-1\big)}{e^{-x}\big(e^x+1\big)}=\RR{\dfrac{1-e^{-x}}{1+e^{-x}}}$ (نضرب البسط والمقام في $e^{-x}$).')
+WARN()+r'\ $e^{x+y}\neq e^x+e^y$ و $e^{xy}\neq e^x\times e^y$.',
TT()+r'\par بسّط العبارات التالية ، ثم أثبت المساواتين:'
+Q(r'$A=e^{x+2}\times e^{-2x+1}$.',r'$B=\dfrac{\big(e^{2x}\big)^3}{e^{x-1}\times e^{5x}}$.',r'$e^{2x}-1=\big(e^x-1\big)\big(e^x+1\big)$.',r'$\dfrac1{1+e^{-x}}=\dfrac{e^x}{e^x+1}$.')
+SOL()+Q(r'$A=e^{x+2-2x+1}=\RR{e^{-x+3}}$.',
   r'$B=\dfrac{e^{6x}}{e^{x-1+5x}}=\dfrac{e^{6x}}{e^{6x-1}}=e^{6x-6x+1}=\RR{e}$.',
   r'$\big(e^x-1\big)\big(e^x+1\big)=\big(e^x\big)^2-1=\RR{e^{2x}-1}$.',
   r'نضرب البسط والمقام في $e^x$: $\dfrac1{1+e^{-x}}=\dfrac{e^x}{e^x+e^xe^{-x}}=\RR{\dfrac{e^x}{e^x+1}}$.')
+HW(r'حل التمرينين 02 و 03 صفحة 102.'),
[r'سؤال تحفيزي.',r'مناقشة النشاط من طرف التلاميذ.',r'الخواص تُبرهن مع التلاميذ.',r'تقويم فردي.']))
