S.append(sess('12',r'دراسة الدوال $x\mapsto e^{u(x)}$ والدوال $x\mapsto e^{kx}$',
[r'اتجاه تغير مركب دالتين ، مشتقة دالة مركبة.'],
[r'تعيين اتجاه تغير ومشتقة الدالة $x\mapsto e^{u(x)}$.',r'توظيف الدوال $x\mapsto e^{kx}$ في النمذجة.'],TOOLS,
r'التذكير بمشتقة دالة مركبة: $(g\circ u)^{\prime}=u^{\prime}\times g^{\prime}\circ u$.',
ACT('03')+r'\ $f(x)=e^{2x+7}$ على $\mathbb R$.'+Q(r'اكتب $f$ على شكل مركب دالتين.',r'استنتج اتجاه تغير $f$.',r'احسب $f^{\prime}(x)$.')
+DIS()+Q(r'$f=\exp\circ u$ حيث $u(x)=2x+7$.',r'$u$ و $\exp$ متزايدتان تمامًا ، إذن \RR{$f$ متزايدة تمامًا على $\mathbb R$}.',r'$f^{\prime}(x)=u^{\prime}(x)\times e^{u(x)}=\RR{2e^{2x+7}}$.'),
PRO('اتجاه التغير')+r'\ إذا كانت $u$ معرفة على مجال $I$ فإن للدالتين $u$ و $\exp\circ u$ \RR{نفس اتجاه التغير} على $I$.'
+PRF()+r'\ الدالة $\exp$ متزايدة تمامًا على $\mathbb R$ ، وحسب مبرهنة اتجاه تغير مركب دالتين: إذا كان لـ $u$ و $\exp$ نفس الاتجاه فإن $\exp\circ u$ متزايدة ، وإلا فهي متناقصة.'
+PRO('المشتقة')+r'\ إذا كانت $u$ قابلة للاشتقاق على $I$ فإن: $\RR{\big[e^{u(x)}\big]^{\prime}=u^{\prime}(x)\,e^{u(x)}}$.'
+EX('أمثلة')+Q(r'$f(x)=e^{x^2-3x+1}$: $\RR{f^{\prime}(x)=(2x-3)e^{x^2-3x+1}}$.',r'$g(x)=e^{\sqrt x}$ على $]0;+\infty[$: $\RR{g^{\prime}(x)=\dfrac1{2\sqrt x}e^{\sqrt x}}$.')
+L('cThm',r'حالة خاصة: الدوال $x\mapsto e^{kx}$')+Q(r'$\big(e^{kx}\big)^{\prime}=ke^{kx}$.',r'إذا كان $k>0$: $x\mapsto e^{kx}$ \RR{متزايدة تمامًا} (نمو).',r'إذا كان $k<0$: $x\mapsto e^{kx}$ \RR{متناقصة تمامًا} (تناقص).')
+EX('نمذجة')+r'\ عدد سكان مدينة (بالآلاف) بعد $t$ سنة: $P(t)=1000\,e^{0{,}02t}$.'+Q(r'$k=0{,}02>0$: \RR{$P$ متزايدة} (السكان يتزايدون).',r'$P(0)=\RR{1000}$ ألف ، و $P(10)=1000e^{0{,}2}\approx\RR{1221{,}4}$ ألف.')
+WARN()+r'\ $\big(e^{u}\big)^{\prime}=u^{\prime}e^{u}$ وليست $e^{u^{\prime}}$.',
TT()+r'\par ادرس اتجاه تغير الدالة $f$ في كل حالة:'+Q(r'$f(x)=x+1-e^{-2x}$ ، $D_f=\mathbb R$.',r'$f(x)=e^{3x}-3e^x$ ، $D_f=\mathbb R$.',r'$f(x)=\dfrac{e^{4x}-3}{e^{4x}+1}$ ، $D_f=\mathbb R$.',r'$f(x)=e^{\frac{x+1}{x-1}}$ ، $D_f=]-\infty;1[\cup]1;+\infty[$.')
+SOL()+Q(r'$f^{\prime}(x)=1-(-2)e^{-2x}=1+2e^{-2x}>0$: \RR{$f$ متزايدة تمامًا على $\mathbb R$}.',
   r'$f^{\prime}(x)=3e^{3x}-3e^x=3e^x\big(e^{2x}-1\big)$ ، وإشارتها إشارة $e^{2x}-1$: موجبة إذا كان $2x>0$:'
   +VAR([r'-\infty','0',r'+\infty'],r'f(x)',r'f^{\prime}(x)',['','-','0','+',''],['','-2',''],['h','l','h'])
   +r'$f(0)=1-3=\RR{-2}$.',
   r'$f^{\prime}(x)=\dfrac{4e^{4x}\big(e^{4x}+1\big)-4e^{4x}\big(e^{4x}-3\big)}{\big(e^{4x}+1\big)^2}=\dfrac{16e^{4x}}{\big(e^{4x}+1\big)^2}>0$: \RR{$f$ متزايدة تمامًا على $\mathbb R$}.',
   r'$u(x)=\dfrac{x+1}{x-1}$ ، $u^{\prime}(x)=\dfrac{(x-1)-(x+1)}{(x-1)^2}=\dfrac{-2}{(x-1)^2}<0$:\par $f^{\prime}(x)=\dfrac{-2}{(x-1)^2}e^{\frac{x+1}{x-1}}<0$: \RR{$f$ متناقصة تمامًا على كل من المجالين}.')
+HW(r'التمرينان 38 و 39 صفحة 104.'),
[r'تذكير بمشتقة مركب.',r'مناقشة النشاط.',r'مثال نمذجة من الواقع.',r'تقويم فردي.']))
