S.append(sess('13',r'المعادلات التفاضلية $y^{\prime}=ay$ و $y^{\prime}=ay+b$',
[r'الدالة الأسية ، مشتقة $x\mapsto e^{kx}$ ، المعادلات التفاضلية $y^{\prime}=f$.'],
[r'حل معادلة تفاضلية من الشكل $y^{\prime}=ay+b$.',r'تعيين الحل الذي يحقق شرطًا ابتدائيًا.'],TOOLS,
r'المعادلة التفاضلية معادلة مجهولها دالة $y$ وتربط بين $y$ ومشتقتها $y^{\prime}$.',
ACT('04')+r'\ $a$ و $c$ عددان حقيقيان ، $a\neq0$.'+Q(r'$f(x)=ce^{ax}$: احسب $f^{\prime}(x)$ وتحقق أن $f^{\prime}=af$.',r'تحقق أن الدالة الثابتة $x\mapsto-\dfrac ba$ حل للمعادلة $y^{\prime}=ay+b$.')
+DIS()+Q(r'$f^{\prime}(x)=c\times ae^{ax}=a\big(ce^{ax}\big)=\RR{af(x)}$: $f$ حل للمعادلة $y^{\prime}=ay$.',r'مشتقة الثابت معدومة ، و $a\left(-\dfrac ba\right)+b=-b+b=\RR{0}$: الدالة الثابتة حل.'),
THM('مبرهنة 1')+r'\ $a$ عدد حقيقي غير معدوم. حلول المعادلة $y^{\prime}=ay$ على $\mathbb R$ هي الدوال $\RR{x\mapsto ce^{ax}}$ حيث $c$ عدد حقيقي ثابت.'
+PRF()+r'\ لتكن $g$ حلًا ، نضع $h(x)=g(x)e^{-ax}$: $h^{\prime}(x)=g^{\prime}(x)e^{-ax}-ag(x)e^{-ax}=\big(ag(x)-ag(x)\big)e^{-ax}=0$.\par إذن $h$ ثابتة: $h(x)=c$ ، ومنه $g(x)=ce^{ax}$.'
+THM('مبرهنة 2')+r'\ $a\neq0$. حلول المعادلة $y^{\prime}=ay+b$ على $\mathbb R$ هي الدوال $\RR{x\mapsto ce^{ax}-\dfrac ba}$ حيث $c$ ثابت حقيقي.'
+PRO('الحل الذي يحقق شرطًا')+r'\ من أجل كل ثنائية $(x_0;y_0)$ ، المعادلة $y^{\prime}=ay+b$ ($a\neq0$) تقبل \RR{حلًا وحيدًا} $f$ يحقق $f(x_0)=y_0$.'
+EX('أمثلة')+Q(r'$y^{\prime}+5y=0$ معناه $y^{\prime}=-5y$: الحلول $\RR{x\mapsto ce^{-5x}}$ ، $c\in\mathbb R$.',
   r'$y^{\prime}=2y+1$: $a=2$ ، $b=1$: الحلول $\RR{x\mapsto ce^{2x}-\dfrac12}$.',
   r'الحل الذي يحقق $f(0)=1$: $c-\dfrac12=1$ ، $c=\dfrac32$: $\RR{f(x)=\dfrac32e^{2x}-\dfrac12}$.')
+WARN()+r'\ نكتب المعادلة على الشكل $y^{\prime}=ay+b$ قبل تطبيق المبرهنة.',
TT()+r'\par نعتبر المعادلة التفاضلية $(E):\ 2y^{\prime}+y=1$.'+Q(r'حل في $\mathbb R$ المعادلة $(E)$.',r'عيّن الحل الخاص $f$ للمعادلة $(E)$ بحيث $f(-1)=2$.',r'ادرس اتجاه تغير $f$ ، والوضع النسبي لمنحناها والمستقيم $y=1$ ، ثم ارسم $(C_f)$.')
+SOL()+Q(r'$(E)$ تكافئ $y^{\prime}=-\dfrac12y+\dfrac12$: $a=-\dfrac12$ ، $b=\dfrac12$ ، $-\dfrac ba=1$:\par الحلول $\RR{x\mapsto ce^{-\frac x2}+1}$ ، $c\in\mathbb R$.',
   r'$f(-1)=ce^{\frac12}+1=2$ ، $c=e^{-\frac12}$: $\RR{f(x)=e^{-\frac{x+1}2}+1}$.',
   r'$f^{\prime}(x)=-\dfrac12e^{-\frac{x+1}2}<0$: \RR{$f$ متناقصة تمامًا على $\mathbb R$}.\par $f(x)-1=e^{-\frac{x+1}2}>0$: \RR{$(C_f)$ فوق المستقيم $(\Delta):y=1$}.'+VP([r'-\infty',r'+\infty'],'f(x)-1',{},['فوق'],'(C_f)',r'(\Delta)')+G13)
+HW(r'التمرين 102 صفحة 109 ، والتمرينان 105 و 106 صفحة 110.'),
[r'تعريف المعادلة التفاضلية.',r'التحقق بالاشتقاق.',r'البرهان مع التلاميذ.',r'نهاية محور الدالة الأسية.']))
